-- =============================================================================
-- NINHO — CATÁLOGO SEMÂNTICO: 03_meta_objeto.sql (PROJETO: GLD)
-- =============================================================================

MERGE INTO DW_GLD.META_OBJETO dst
USING (SELECT 'GLD' AS PROJETO, 'VW_GLD_DIM_ORGAO_PUBLICO_ATUAL' AS NOME_OBJETO, 'DIMENSAO' AS TIPO_OBJETO, 'ORGAO_PUBLICO' AS DOMINIO, 'Uma linha representa 1 ID_ORGAO vigente' AS GRAO, 'DW_GLD' AS SCHEMA_ORIGEM, 'DIM_ORGAO_PUBLICO' AS OBJETO_FISICO, 'S' AS IND_GOVERNADO, 'S' AS IND_ATIVO FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.NOME_OBJETO = src.NOME_OBJETO)
WHEN MATCHED THEN UPDATE SET dst.TIPO_OBJETO = src.TIPO_OBJETO, dst.GRAO = src.GRAO, dst.OBJETO_FISICO = src.OBJETO_FISICO
WHEN NOT MATCHED THEN INSERT (PROJETO, NOME_OBJETO, TIPO_OBJETO, DOMINIO, GRAO, SCHEMA_ORIGEM, OBJETO_FISICO, IND_GOVERNADO, IND_ATIVO, DT_INICIO_VIGENCIA)
VALUES (src.PROJETO, src.NOME_OBJETO, src.TIPO_OBJETO, src.DOMINIO, src.GRAO, src.SCHEMA_ORIGEM, src.OBJETO_FISICO, src.IND_GOVERNADO, src.IND_ATIVO, SYSDATE);

